/**
 * File-format edge cases: audio-only, no audio, MKV, embedded subtitles.
 * Uses the sample generated by tests/file-e2e.mjs.
 *
 * Run: node tests/file-e2e.mjs && node tests/formats-e2e.mjs
 */

import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { probe, resolveFfmpeg } from '../lib/core/media.js'
import { processFile } from '../lib/core/pipeline.js'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const TMP = path.join(HERE, '.tmp-formats-e2e')
const SAMPLE = path.join(HERE, '.tmp-file-e2e', 'sample.mp4')
const ffmpeg = resolveFfmpeg()
assert.ok(ffmpeg, 'ffmpeg not found')
assert.ok(fs.existsSync(SAMPLE), 'run tests/file-e2e.mjs first (sample.mp4 missing)')

fs.rmSync(TMP, { recursive: true, force: true })
fs.mkdirSync(TMP, { recursive: true })

function ffmpegRun(args) {
  const result = spawnSync(ffmpeg, ['-hide_banner', '-loglevel', 'error', ...args], {
    stdio: 'ignore',
    windowsHide: true,
    timeout: 120_000,
  })
  assert.equal(result.status, 0, `ffmpeg failed: ${args.join(' ')}`)
}

const audio = path.join(TMP, 'audio.m4a')
ffmpegRun(['-i', SAMPLE, '-vn', '-c:a', 'aac', '-b:a', '96k', '-y', audio])

const audioResult = await processFile({
  input: audio,
  language: 'zh',
  subtitle: 'soft',
  threads: 4,
  outDir: path.join(TMP, 'out-audio'),
  workDir: path.join(TMP, 'work-audio'),
})
assert.equal(audioResult.softVideo, null, 'audio-only should not produce a video')
assert.equal(audioResult.hardVideo, null, 'audio-only should not produce a hard-sub video')
const audioManifest = JSON.parse(fs.readFileSync(path.join(TMP, 'out-audio', 'session.json'), 'utf8'))
assert.equal(audioManifest.stats.mediaKind, 'audio')
assert.ok(fs.existsSync(path.join(TMP, 'out-audio', 'transcript.md')))
assert.ok(fs.existsSync(path.join(TMP, 'out-audio', 'subtitles.srt')))
console.log('[formats-e2e] audio-only PASS')

const noAudio = path.join(TMP, 'no-audio.mp4')
ffmpegRun(['-i', SAMPLE, '-an', '-c:v', 'copy', '-y', noAudio])
await assert.rejects(
  processFile({
    input: noAudio,
    language: 'zh',
    subtitle: 'soft',
    threads: 4,
    outDir: path.join(TMP, 'out-no-audio'),
    workDir: path.join(TMP, 'work-no-audio'),
  }),
  /没有音频流/,
)
assert.equal(fs.existsSync(path.join(TMP, 'out-no-audio', 'session.json')), false)
console.log('[formats-e2e] no-audio PASS')

const mkv = path.join(TMP, 'media.mkv')
ffmpegRun(['-i', SAMPLE, '-c', 'copy', '-y', mkv])
const mkvResult = await processFile({
  input: mkv,
  language: 'zh',
  subtitle: 'soft',
  threads: 4,
  outDir: path.join(TMP, 'out-mkv'),
  workDir: path.join(TMP, 'work-mkv'),
})
assert.ok(mkvResult.softVideo && mkvResult.softVideo.endsWith('.soft.mkv'))
const mkvInfo = await probe(mkvResult.softVideo)
assert.ok(mkvInfo.subtitleStreams.length >= 1, 'MKV soft output has no subtitle stream')
console.log('[formats-e2e] MKV PASS')

const srt = path.join(TMP, 'embedded.srt')
fs.writeFileSync(srt, '1\n00:00:00,500 --> 00:00:03,000\n内嵌字幕测试\n', 'utf8')
const embedded = path.join(TMP, 'embedded.mkv')
ffmpegRun(['-i', mkv, '-i', srt, '-map', '0', '-map', '1', '-c', 'copy', '-c:s', 'srt', '-y', embedded])
const subsResult = await processFile({
  input: embedded,
  subsOnly: true,
  outDir: path.join(TMP, 'out-subs'),
  workDir: path.join(TMP, 'work-subs'),
})
assert.ok(fs.readFileSync(subsResult.srt, 'utf8').includes('内嵌字幕测试'))
console.log('[formats-e2e] embedded subtitles PASS')

console.log('[formats-e2e] ALL PASS')
